export function getSampleDocumentsAsSheetRows(): SheetRow[] {
  return RAW_SAMPLE_DOCUMENTS.map((doc) => {
    const isCorp = doc.statusLabor.includes("บริษัท") || doc.statusLabor.includes("นิติบุคคล") || doc.name.includes("บริษัท") || doc.name.includes("หจก");
    const net = Math.round((doc.wageAmount - doc.taxAmount) * 100) / 100;
    
    return {
      id: doc.id,
      "ลำดับ": doc.id,
      "ลำดับtest": doc.id,
      "ว/ด/ป": doc.date,
      "วันที่": doc.date,
      "ร้าน/บุคคล": doc.name,
      "ผู้รับเหมา": doc.name,
      "ชื่อ-นามสกุล": doc.name,
      "บัตรประจำตัวประชาชน": doc.taxId,
      "เลขประจำตัวประชาชน": doc.taxId,
      "เลขประจำตัวผู้เสียภาษี": doc.taxId,
      "ที่อยู่": doc.address,
      "ยอดเงิน": doc.wageAmount,
      "ค่าจ้าง": doc.wageAmount,
      "ค่าแรง": doc.wageAmount,
      "ค่าแรง+พนักงาน+อื่นๆ": doc.wageAmount,
      "0.03": doc.baseAmount,
      "หัก": doc.taxAmount > 0 ? "3%" : "0%",
      "หัก 3%": doc.taxAmount,
      "3เปอร์เซ็น": doc.taxAmount,
      "จำนวนหัก": doc.taxAmount,
      "คงเหลือ": net,
      "ยอดโอน": net,
      "คงเหลือรับสุทธิ": net,
      "ผู้จ่าย": doc.issuer,
      "ผู้ออก": doc.issuer,
      "ผู้เบิก": doc.issuer,
      "สินค้า/ทำงาน": doc.jobDescription,
      "รายละเอียดงาน": doc.jobDescription,
      "ชื่องาน หรือ หมายเหตุ": doc.jobDescription,
      "Statusค่าแรง": doc.statusLabor,
      "statusค่าแรง": doc.statusLabor,
      "ประเภท": isCorp ? "บริษัท" : "ค่าแรง (บุคคลธรรมดา)",
      "ร้านค้า/ผู้รับเหมา": isCorp ? "ร้านค้า" : "ผู้รับเหมา",
      "สถานะ": "อนุมัติแล้ว",
      _sheetRow: doc.id,
      _isSample: true
    } as SheetRow;
  });
}
